CREATE TABLE return_journeys(id text PRIMARY KEY,dispute_id text NOT NULL REFERENCES disputes(id),buyer_id text NOT NULL REFERENCES users(id),seller_id text NOT NULL REFERENCES users(id),driver_id text REFERENCES users(id),status text NOT NULL DEFAULT 'ASSIGNED' CHECK(status IN ('ASSIGNED','ACCEPTED','PICKED_UP','RETURNED','CANCELLED')),pickup_address text NOT NULL,pickup_latitude double precision NOT NULL CHECK(pickup_latitude BETWEEN -90 AND 90),pickup_longitude double precision NOT NULL CHECK(pickup_longitude BETWEEN -180 AND 180),dropoff_address text NOT NULL,dropoff_latitude double precision NOT NULL CHECK(dropoff_latitude BETWEEN -90 AND 90),dropoff_longitude double precision NOT NULL CHECK(dropoff_longitude BETWEEN -180 AND 180),fee_kobo integer NOT NULL CHECK(fee_kobo>0 AND fee_kobo<=100000000),driver_kobo integer NOT NULL CHECK(driver_kobo>=0 AND driver_kobo<=fee_kobo),payer_account text NOT NULL CHECK(payer_account IN ('wallet','seller_payable','platform_revenue')),payer_id text,pickup_pin text NOT NULL,return_pin text NOT NULL,pin_failures integer NOT NULL DEFAULT 0,pin_locked_until timestamptz,reason text NOT NULL,reviewed_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX return_journeys_driver_idx ON return_journeys(driver_id,status);

CREATE UNIQUE INDEX return_journeys_open_case_idx ON return_journeys(dispute_id) WHERE status<>'CANCELLED';
